import {hero,team} from './engine.js?v=3.5.0';
import {investmentQuote,cents} from './finance.js?v=3.5.0';
import {projectSnapshot} from './club-project.js?v=3.5.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' €';
const select=(id,label,value,options)=>`<label>${label}<select id="${id}">${options.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;
const button=(label,action,disabled=false)=>`<button class="secondary" data-action="life:${action}" ${disabled?'disabled':''}>${label}</button>`;
export function clubProjectView(s){const t=team(s),p=projectSnapshot(s,t);return `<section class="panel"><p class="eyebrow">PROJET DU CLUB</p><h3>${esc(t.name)} · ${esc(p.strategy)}</h3><p>${esc(p.reason)}</p><p>${['Reconstruction','Développement'].includes(p.strategy)?'Priorité modérée aux joueurs de 23 ans ou moins dans les rotations (+3 dans la sélection du cinq).':'La rotation privilégie le niveau et la disponibilité.'}</p><p>Engagements : ${money(p.payroll)} · budget cible : ${money(t.budget)}.</p>${p.overBudget?`<p>Budget dépassé de ${money(p.overBudget)} : les salaires signés restent garantis. Les nouvelles offres sont limitées ; un minimum de simulation permet de compléter l’effectif.</p>`:''}<details><summary>Décisions du club</summary>${(t.projectHistory||[]).slice(0,15).map(e=>`<p><b>S${e.season} · ${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')||'<p>Pas encore de mouvement enregistré.</p>'}</details></section>`;}
export function lifeView(s){const l=s.life,f=l.finance,blocked=!!s.pending||!!s.match||s.retired;
 return `<section class="panel"><h2>Votre entourage</h2><div class="metrics">${[['Moral',l.morale],['Notoriété',l.fame],['Famille',l.family]].map(([k,v])=>`<article><span>${k}</span><strong>${Math.round(v)}</strong></article>`).join('')}</div><p>${l.partner?`<b>${esc(l.partner.name)}</b> · partenaire depuis J${l.partner.since} · complicité ${Math.round(l.partner.bond)}/100`:'Une rencontre peut ouvrir un chapitre à partir de 18 ans.'}</p><p>${l.children.map(c=>`${esc(c.name)} · ${Math.max(0,Math.floor((s.day-c.born)/365))} ans`).join('<br>')||'Pas d’enfant.'}</p>${l.expecting?`<p>Un enfant est attendu dans environ ${Math.max(0,Math.ceil((l.expecting-s.day)/30))} mois.</p>`:''}<div class="stat-strip">${Object.entries(l.people).map(([key,p])=>`<div><strong>${esc(p.name)}</strong><span>${esc(p.role)} · ${Math.round(s.relationships[key==='close'?'family':key]||0)}/100</span></div>`).join('')}</div><details><summary>Histoires et souvenirs · ${l.history.length}</summary>${l.stories.filter(x=>x.status==='active').map(x=>`<p>En cours · ${esc(x.text)} · suivi prévu après J${x.due}.</p>`).join('')}${l.history.slice(-40).reverse().map(e=>`<p>J${e.day} · <b>${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')||'<p>Votre histoire commence.</p>'}</details></section>
 <section class="panel"><h2>Vos consignes durables</h2><div class="two-col">${select('policy-routine','Routine personnelle',l.policies.routine,[['manual','Me demander'],['family','Privilégier les proches'],['rest','Privilégier la récupération'],['work','Travailler avec le mentor']])}${select('policy-media','Médias',l.policies.media,[['manual','Me demander'],['team','Mettre le collectif en avant'],['rest','Laisser répondre mon agent'],['ambition','Affirmer mes ambitions']])}${select('policy-agent','Partenariats locaux',l.policies.agent,[['manual','Me demander'],['local','Accepter les propositions locales'],['rest','Refuser les sollicitations']])}${select('policy-exposure','Exposition souhaitée',l.preferences.exposure,[['local','Locale · peu d’obligations'],['national','Nationale · décision personnelle'],['none','Aucun partenariat']])}</div><p class="muted">Rencontre, projet de famille, changement de ville et engagement national restent des décisions personnelles. Votre agent ne signe jamais un contrat sportif à votre place. Les autres choix suivent vos consignes et figurent ci-dessous.</p><details><summary>Décisions déléguées · ${l.delegationLog.length}</summary>${l.delegationLog.slice(0,30).map(e=>`<p>J${e.day} · <b>${esc(e.title)}</b><br>${esc(e.choice)} · ${esc(e.reason)}${e.effect?'<br>'+esc(e.effect):''}</p>`).join('')||'<p>Aucune décision déléguée.</p>'}</details></section>
 <div class="two-col"><section class="panel"><h2>Finances personnelles</h2><h3>${money(s.money+l.investments+(l.property?.value||0))} de patrimoine</h3><p>Disponible : <b>${money(s.money)}</b><br>Placements : <b>${money(l.investments)}</b><br>Résidence : ${l.property?money(l.property.value)+' · '+esc(l.property.city):'Aucune'}</p>${select('lifestyle','Train de vie',l.lifestyle,[['simple','Simple'],['comfortable','Confortable'],['premium','Premium']])}${select('finance-percent','Part à placer au-delà de la réserve',f.percent,[0,10,20,30,50].map(v=>[v,v+' %']))}${select('finance-reserve','Réserve de liquidités',f.reserve,[0,5000,25000,100000].map(v=>[v,money(v)]))}${select('finance-frequency','Fréquence automatique',f.frequency,[[30,'Tous les 30 jours'],[90,'Tous les 90 jours']])}<label class="check"><input type="checkbox" id="finance-automatic" ${f.automatic?'checked':''}> Appliquer automatiquement cette règle</label><p>Prochain placement à cet instant : <b>${money(investmentQuote(s))}</b> (${f.percent} % de la somme au-delà de ${money(f.reserve)}, sans plafond). ${f.automatic?'Prochaine échéance à partir de J'+Math.max(s.day,f.lastDay+f.frequency)+'.':''}</p><div class="button-row">${button('Placer '+money(investmentQuote(s)),'invest',blocked||investmentQuote(s)<.01)}${button('Retirer '+money(Math.min(100000,l.investments))+' · plafond 100 000 €','withdraw',blocked||!l.investments)}${button('Acheter une résidence · 250 000 €','property',blocked||!!l.property||s.money<250000)}${l.property?button('Vendre · net '+money(cents(l.property.value*.95))+' · frais 5 %','sell',blocked)+button('Déménager vers '+esc(team(s).name)+' · 5 000 €','move',blocked||s.money<5000||l.property.city===team(s).name):''}</div><p class="muted">Règles de jeu : salaire net de 76 %, placements variables, logement +1,5 % par an. Déménager conserve la valeur du bien et coûte 5 000 €. La vente déduit 5 % de frais.</p><details><summary>Relevé · liquidités et patrimoine</summary><p>Depuis le suivi V3.5 : liquidités ${money(f.totals.cash)}, placements ${money(f.totals.investments)}, immobilier ${money(f.totals.property)}. Les revenus sont comptés au montant réellement reçu chaque jour.</p>${l.ledger.slice(0,90).map(e=>`<p>J${e.day} · ${esc(e.label)}<br>Disponible ${money(e.cash??e.amount)}${e.investments?' · placements '+money(e.investments):''}${e.property?' · immobilier '+money(e.property):''}</p>`).join('')}</details></section>
 <section class="panel"><h2>Sponsors et exposition</h2>${l.sponsors.map(c=>`<h3>${esc(c.name)}</h3><p>${money(c.annual)} / an · échéance J${c.ends} · ${c.obligation} rendez-vous de simulation par mois.</p>`).join('')||'<p>Les marques attendent une carrière professionnelle et une notoriété d’au moins 18.</p>'}<p>Les propositions tiennent compte de votre notoriété, de vos titres, du championnat et de l’exposition acceptée.</p><p>Vos engagements prennent du temps : chaque mois, la fatigue augmente du nombre de rendez-vous prévus (maximum 6).</p></section></div>`;
}
